def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append((color, cells))

    repaired = set()
    for color, cells in components:
        r0 = min(r for r, c in cells)
        r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells)
        c1 = max(c for r, c in cells)
        area = (r1 - r0 + 1) * (c1 - c0 + 1)
        if area == len(cells) + 1:
            missing = [(r, c) for r in range(r0, r1 + 1)
                       for c in range(c0, c1 + 1)
                       if grid[r][c] != color]
            if len(missing) == 1:
                r, c = missing[0]
                if grid[r][c] != bg:
                    out[r][c] = color
                    repaired.add((r, c))

    for color, cells in components:
        if len(cells) == 1:
            r, c = cells[0]
            if (r, c) not in repaired:
                out[r][c] = bg

    return out
